1	<!doctype html>
2	<html lang="en">
3	<head>
4	  <meta charset="utf-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1">
6	  <title>Trove — bookmark prototype</title>
7	  <style>
8	    :root {
9	      color-scheme: light;
10	      --ink: #19231f;
11	      --muted: #63706a;
12	      --paper: #f4f0e6;
13	      --card: #fffdf7;
14	      --line: #d9d3c5;
15	      --accent: #176b51;
16	      --accent-dark: #0e513c;
17	    }
18	    * { box-sizing: border-box; }
19	    body {
20	      margin: 0;
21	      min-height: 100vh;
22	      background:
23	        radial-gradient(circle at 80% 5%, rgba(239, 181, 82, .17), transparent 26rem),
24	        var(--paper);
25	      color: var(--ink);
26	      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
27	    }
28	    header, main { width: min(980px, calc(100% - 40px)); margin-inline: auto; }
29	    header {
30	      display: flex;
31	      align-items: baseline;
32	      justify-content: space-between;
33	      padding: 32px 0 22px;
34	      border-bottom: 1px solid var(--line);
35	    }
36	    .brand { font: 700 1.55rem Georgia, serif; letter-spacing: -.02em; }
37	    .count { color: var(--muted); font-size: .9rem; }
38	    main { padding: 56px 0 100px; }
39	    h1 { max-width: 600px; margin: 0 0 10px; font: 700 clamp(2rem, 5vw, 3.25rem)/1.04 Georgia, serif; letter-spacing: -.035em; }
40	    .lede { margin: 0 0 28px; color: var(--muted); font-size: 1.05rem; }
41	    form {
42	      display: grid;
43	      grid-template-columns: 1fr auto;
44	      gap: 10px;
45	      max-width: 760px;
46	      padding: 9px;
47	      border: 1px solid var(--line);
48	      border-radius: 14px;
49	      background: var(--card);
50	      box-shadow: 0 10px 35px rgba(38, 47, 42, .07);
51	    }
52	    input {
53	      min-width: 0;
54	      border: 0;
55	      outline: none;
56	      background: transparent;
57	      color: var(--ink);
58	      padding: 12px 13px;
59	      font: inherit;
60	    }
61	    button {
62	      border: 0;
63	      border-radius: 9px;
64	      background: var(--accent);
65	      color: white;
66	      padding: 0 21px;
67	      min-height: 46px;
68	      font-weight: 700;
69	      cursor: pointer;
70	    }
71	    button:hover { background: var(--accent-dark); }
72	    .status { min-height: 24px; margin: 12px 4px; color: var(--muted); font-size: .91rem; }
73	    .status.success { color: var(--accent-dark); }
74	    .collection { margin-top: 54px; }
75	    .collection-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 15px; }
76	    h2 { margin: 0; font: 700 1.25rem Georgia, serif; }
77	    .empty {
78	      border: 1px dashed #c7c0b2;
79	      border-radius: 14px;
80	      padding: 44px 24px;
81	      text-align: center;
82	      color: var(--muted);
83	      background: rgba(255, 253, 247, .45);
84	    }
85	    .bookmark {
86	      display: grid;
87	      grid-template-columns: 1fr auto;
88	      gap: 22px;
89	      align-items: center;
90	      border: 1px solid var(--line);
91	      border-radius: 14px;
92	      padding: 21px 22px;
93	      background: var(--card);
94	      box-shadow: 0 8px 25px rgba(38, 47, 42, .055);
95	    }
96	    .bookmark h3 { margin: 5px 0 7px; font: 700 1.18rem Georgia, serif; }
97	    .bookmark p { max-width: 650px; margin: 0; color: var(--muted); line-height: 1.45; }
98	    .domain { color: var(--accent); font-size: .8rem; font-weight: 800; letter-spacing: .06em; text-transform: uppercase; }
99	    .saved { color: var(--muted); font-size: .82rem; white-space: nowrap; }
100	    @media (max-width: 620px) {
101	      main { padding-top: 38px; }
102	      form { grid-template-columns: 1fr; }
103	      button { min-height: 48px; }
104	      .bookmark { grid-template-columns: 1fr; gap: 12px; }
105	    }
106	  </style>
107	</head>
108	<body>
109	  <header>
110	    <div class="brand">Trove</div>
111	    <div class="count" id="count">0 bookmarks</div>
112	  </header>
113	  <main data-harness-ready="true">
114	    <h1>Keep what’s worth finding again.</h1>
115	    <p class="lede">Save a page now. We’ll fill in the useful details.</p>
116	
117	    <form id="save-form">
118	      <input id="url" type="url" aria-label="Web address" value="https://example.com/articles/calm-reading-habit" required>
119	      <button type="submit">Save bookmark</button>
120	    </form>
121	    <div class="status" id="status" aria-live="polite">The sample address is ready to save.</div>
122	
123	    <section class="collection" aria-labelledby="collection-title">
124	      <div class="collection-head">
125	        <h2 id="collection-title">Your bookmarks</h2>
126	      </div>
127	      <div id="bookmarks">
128	        <div class="empty">Your saved pages will appear here.</div>
129	      </div>
130	    </section>
131	  </main>
132	  <script>
133	    const form = document.querySelector('#save-form');
134	    const input = document.querySelector('#url');
135	    const status = document.querySelector('#status');
136	    const list = document.querySelector('#bookmarks');
137	    const count = document.querySelector('#count');
138	
139	    form.addEventListener('submit', (event) => {
140	      event.preventDefault();
141	      const parsed = new URL(input.value);
142	      const title = parsed.hostname === 'example.com'
143	        ? 'A calmer way to build a reading habit'
144	        : `Saved page from ${parsed.hostname.replace(/^www\\./, '')}`;
145	      const description = parsed.hostname === 'example.com'
146	        ? 'A practical guide to choosing what to read, making time for it, and retaining the ideas that matter.'
147	        : 'Page details were collected automatically so this bookmark is easy to recognize later.';
148	      list.innerHTML = `
149	        <article class="bookmark">
150	          <div>
151	            <div class="domain">${parsed.hostname.replace(/^www\\./, '')}</div>
152	            <h3>${title}</h3>
153	            <p>${description}</p>
154	          </div>
155	          <div class="saved">Saved just now</div>
156	        </article>`;
157	      count.textContent = '1 bookmark';
158	      status.textContent = 'Saved — title and description added automatically.';
159	      status.className = 'status success';
160	      input.value = '';
161	    });
162	  </script>
163	</body>
164	</html>
