113	<body>
114	  <header>
115	    <div class="brand">Trove</div>
116	    <div class="count" id="count">0 bookmarks</div>
117	  </header>
118	  <main data-harness-ready="true">
119	    <h1>Keep what’s worth finding again.</h1>
120	    <p class="lede">Save a page now. We’ll fill in the useful details.</p>
121	
122	    <form id="save-form">
123	      <input id="url" type="url" aria-label="Web address" value="https://example.com/articles/calm-reading-habit" required>
124	      <button type="submit">Save bookmark</button>
125	    </form>
126	    <div class="status" id="status" aria-live="polite">The sample address is ready to save.</div>
127	
128	    <div class="search-wrap" id="search-wrap" hidden>
129	      <label for="search">Find a saved page</label>
130	      <input class="search-box" id="search" type="search" placeholder="Search titles and page details">
131	    </div>
132	
133	    <section class="collection" aria-labelledby="collection-title">
134	      <div class="collection-head">
135	        <h2 id="collection-title">Your bookmarks</h2>
136	      </div>
137	      <div id="bookmarks">
138	        <div class="empty">Your saved pages will appear here.</div>
139	      </div>
140	    </section>
141	  </main>
142	  <script>
143	    const form = document.querySelector('#save-form');
144	    const input = document.querySelector('#url');
145	    const status = document.querySelector('#status');
146	    const list = document.querySelector('#bookmarks');
147	    const count = document.querySelector('#count');
148	    const searchWrap = document.querySelector('#search-wrap');
149	    const search = document.querySelector('#search');
150	    const mode = new URLSearchParams(location.search).get('flow') || 'save';
151	
152	    const sampleBookmarks = [
153	      { domain: 'alistapart.com', title: 'Designing for understanding', description: 'How thoughtful structure and language help people make sense of complex interfaces.', saved: 'Saved today' },
154	      { domain: 'nesslabs.com', title: 'A calmer way to build a reading habit', description: 'A practical guide to choosing what to read and retaining the ideas that matter.', saved: 'Saved yesterday' },
155	      { domain: 'hbr.org', title: 'How to focus on meaningful work', description: 'A field guide to protecting attention and making room for deep, focused work.', saved: 'Saved 3 days ago' },
156	      { domain: 'every-layout.dev', title: 'Rethinking flexible page layouts', description: 'Resilient layout patterns for interfaces that work across different screen sizes.', saved: 'Saved last week' }
157	    ];
158	
159	    function bookmarkMarkup(bookmark) {
160	      return `<article class="bookmark">
161	        <div>
162	          <div class="domain">${bookmark.domain}</div>
163	          <h3>${bookmark.title}</h3>
164	          <p>${bookmark.description}</p>
165	        </div>
166	        <div class="saved">${bookmark.saved}</div>
167	      </article>`;
168	    }
169	
170	    function renderSearchResults(query = '') {
171	      const normalized = query.trim().toLocaleLowerCase();
172	      const matches = sampleBookmarks.filter((bookmark) =>
173	        [bookmark.title, bookmark.description, bookmark.domain]
174	          .some((value) => value.toLocaleLowerCase().includes(normalized))
175	      );
176	      count.textContent = `${matches.length} of ${sampleBookmarks.length} bookmarks`;
177	      list.innerHTML = matches.length
178	        ? matches.map(bookmarkMarkup).join('')
179	        : '<div class="no-results">No saved pages match that search.</div>';
180	    }
181	
182	    if (mode === 'search') {
183	      document.querySelector('h1').textContent = 'Find what you saved.';
184	      document.querySelector('.lede').textContent = 'Search the details you can remember — capitalization doesn’t matter.';
185	      form.hidden = true;
186	      status.hidden = true;
187	      searchWrap.hidden = false;
188	      renderSearchResults();
189	      search.addEventListener('input', () => renderSearchResults(search.value));
190	    }
191	
192	    form.addEventListener('submit', (event) => {
193	      event.preventDefault();
194	      const parsed = new URL(input.value);
195	      const title = parsed.hostname === 'example.com'
196	        ? 'A calmer way to build a reading habit'
197	        : `Saved page from ${parsed.hostname.replace(/^www\\./, '')}`;
198	      const description = parsed.hostname === 'example.com'
199	        ? 'A practical guide to choosing what to read, making time for it, and retaining the ideas that matter.'
200	        : 'Page details were collected automatically so this bookmark is easy to recognize later.';
201	      list.innerHTML = bookmarkMarkup({ domain: parsed.hostname.replace(/^www\\./, ''), title, description, saved: 'Saved just now' });
202	      count.textContent = '1 bookmark';
203	      status.textContent = 'Saved — title and description added automatically.';
204	      status.className = 'status success';
205	      input.value = '';
206	    });
207	  </script>
208	</body>
209	</html>
