function bookmarkMarkup(bookmark) {
  return `<article class="bookmark">
    <div>
      <div class="domain">${bookmark.domain}</div>
      <h3>${bookmark.title}</h3>
      <p>${bookmark.description}</p>
      ${bookmark.tags ? `<div class="tags">${bookmark.tags.map(tag => `<button class="tag" type="button" data-tag="${tag}">${tag}</button>`).join('')}</div>` : ''}
    </div>
    <div class="saved">${bookmark.saved}</div>
  </article>`;
}

function renderSearchResults(query = '') {
  const normalized = query.trim().toLocaleLowerCase();
  const matches = sampleBookmarks.filter((bookmark) =>
    [bookmark.title, bookmark.description, bookmark.domain]
      .some((value) => value.toLocaleLowerCase().includes(normalized))
  );
  count.textContent = `${matches.length} of ${sampleBookmarks.length} bookmarks`;
  list.innerHTML = matches.length
    ? matches.map(bookmarkMarkup).join('')
    : '<div class="no-results">No saved pages match that search.</div>';
}

if (mode === 'search') {
  document.querySelector('h1').textContent = 'Find what you saved.';
  document.querySelector('.lede').textContent = 'Search the details you can remember — capitalization doesn’t matter.';
  form.hidden = true;
  status.hidden = true;
  searchWrap.hidden = false;
  renderSearchResults();
  search.addEventListener('input', () => renderSearchResults(search.value));
}

if (mode === 'tags') {
  document.querySelector('h1').textContent = 'Browse by what matters.';
  document.querySelector('.lede').textContent = 'Choose a tag on any bookmark to focus the collection on that topic.';
  form.hidden = true;
  status.hidden = true;
  renderTagResults();
  list.addEventListener('click', (event) => {
    const tagButton = event.target.closest('[data-tag]');
    if (tagButton) renderTagResults(tagButton.dataset.tag);
  });
  filterState.addEventListener('click', (event) => {
    if (event.target.closest('.clear-filter')) renderTagResults();
  });
}

function renderTagResults(activeTag = '') {
  const matches = activeTag
    ? sampleBookmarks.filter(bookmark => bookmark.tags.includes(activeTag))
    : sampleBookmarks;
  collectionTitle.textContent = activeTag ? activeTag : 'Your bookmarks';
  count.textContent = activeTag ? `${matches.length} tagged ${activeTag}` : `${matches.length} bookmarks`;
  filterState.innerHTML = activeTag
    ? '<button class="clear-filter" type="button">Show all</button>'
    : '<span class="filter-note">All topics</span>';
  list.innerHTML = matches.map(bookmarkMarkup).join('');
}

if (mode === 'readlater') {
  const variant = params.get('variant') || 'button';
  const queued = new Set(params.get('state') === 'queued' ? ['designing'] : []);
  let currentView = params.get('view') === 'later' ? 'later' : 'all';
  document.querySelector('h1').textContent = 'Keep a short list for later.';
  document.querySelector('.lede').textContent = 'Set aside a saved page without losing it in the rest of your collection.';
  form.hidden = true;
  status.hidden = true;
  readLaterNav.hidden = false;

  function queueControl(bookmark) {
    const selected = queued.has(bookmark.id);
    if (variant === 'check') {
      return `<label class="queue-check"><input type="checkbox" data-queue="${bookmark.id}" ${selected ? 'checked' : ''}> Read later</label>`;
    }
    if (variant === 'icon') {
      return `<button class="queue-icon ${selected ? 'selected' : ''}" type="button" data-queue="${bookmark.id}"><span aria-hidden="true">${selected ? '★' : '☆'}</span><span>${selected ? 'Saved for later' : 'Save for later'}</span></button>`;
    }
    return `<button class="queue-action ${selected ? 'selected' : ''}" type="button" data-queue="${bookmark.id}">${selected ? '✓ In read later' : '+ Read later'}</button>`;
  }

  function readLaterMarkup(bookmark) {
    const base = bookmarkMarkup(bookmark);
    const control = currentView === 'later'
      ? `<div class="queue-control"><button class="done-action" type="button" data-done="${bookmark.id}">Mark as read</button></div>`
      : `<div class="queue-control">${queueControl(bookmark)}</div>`;
    return base.replace('</div>\n        <div class="saved">', `${control}</div>\n        <div class="saved">`);
  }

  function renderReadLater() {
    const visible = currentView === 'later'
      ? sampleBookmarks.filter(bookmark => queued.has(bookmark.id))
      : sampleBookmarks;
    collectionTitle.textContent = currentView === 'later' ? 'Read later' : 'Your bookmarks';
    count.textContent = currentView === 'later' ? `${visible.length} to read` : `${visible.length} bookmarks`;
    laterCount.textContent = queued.size;
    list.innerHTML = visible.length ? visible.map(readLaterMarkup).join('') : '<div class="empty">Nothing waiting to be read.</div>';
    document.querySelectorAll('[data-view]').forEach(button => button.classList.toggle('active', button.dataset.view === currentView));
    if (currentView === 'all') {
      filterState.innerHTML = `<div class="variant-strip" aria-label="Read-later control variations">
        <a class="variant-link ${variant === 'button' ? 'active' : ''}" href="?flow=readlater&variant=button">A</a>
        <a class="variant-link ${variant === 'check' ? 'active' : ''}" href="?flow=readlater&variant=check">B</a>
        <a class="variant-link ${variant === 'icon' ? 'active' : ''}" href="?flow=readlater&variant=icon">C</a>
      </div>`;
    } else {
      filterState.innerHTML = '';
    }
  }

  list.addEventListener('click', (event) => {
    const queueTarget = event.target.closest('[data-queue]');
    if (queueTarget) {
      const id = queueTarget.dataset.queue;
      if (queued.has(id)) queued.delete(id); else queued.add(id);
      renderReadLater();
    }
    const doneTarget = event.target.closest('[data-done]');
    if (doneTarget) {
      queued.delete(doneTarget.dataset.done);
      renderReadLater();
    }
  });
  list.addEventListener('change', (event) => {
    const queueTarget = event.target.closest('[data-queue]');
    if (queueTarget) {
      if (queueTarget.checked) queued.add(queueTarget.dataset.queue); else queued.delete(queueTarget.dataset.queue);
      renderReadLater();
    }
  });
  readLaterNav.addEventListener('click', (event) => {
    const viewButton = event.target.closest('[data-view]');
    if (viewButton) {
      currentView = viewButton.dataset.view;
      renderReadLater();
    }
  });
  renderReadLater();
}

