  list.addEventListener('click', (event) => {
    const queueTarget = event.target.closest('[data-queue]');
    if (queueTarget) {
      const id = queueTarget.dataset.queue;
      if (queued.has(id)) queued.delete(id); else queued.add(id);
      renderReadLater();
    }
    const doneTarget = event.target.closest('[data-done]');
    if (doneTarget) {
      queued.delete(doneTarget.dataset.done);
      renderReadLater();
    }
  });
  list.addEventListener('change', (event) => {
    const queueTarget = event.target.closest('[data-queue]');
    if (queueTarget) {
      if (queueTarget.checked) queued.add(queueTarget.dataset.queue); else queued.delete(queueTarget.dataset.queue);
      renderReadLater();
    }
  });
  readLaterNav.addEventListener('click', (event) => {
    const viewButton = event.target.closest('[data-view]');
    if (viewButton) {
      currentView = viewButton.dataset.view;
      renderReadLater();
    }
  });
  renderReadLater();
}

form.addEventListener('submit', (event) => {
  event.preventDefault();
  if (mode === 'duplicate') {
    status.innerHTML = 'Already saved — showing your existing bookmark. <button class="inline-action" type="button">Edit existing</button>';
    status.className = 'status success';
    list.querySelector('.bookmark').classList.add('attention');
    count.textContent = '1 bookmark';
    return;
  }
  const parsed = new URL(input.value);
  const title = parsed.hostname === 'example.com'
    ? 'A calmer way to build a reading habit'
    : `Saved page from ${parsed.hostname.replace(/^www\\./, '')}`;
  const description = parsed.hostname === 'example.com'
    ? 'A practical guide to choosing what to read, making time for it, and retaining the ideas that matter.'
    : 'Page details were collected automatically so this bookmark is easy to recognize later.';
  list.innerHTML = bookmarkMarkup({ domain: parsed.hostname.replace(/^www\\./, ''), title, description, saved: 'Saved just now' });

