  function removeBookmark(id) {
    const index = activeBookmarks.findIndex(bookmark => bookmark.id === id);
    if (index < 0) return;
    lastDeleted = { bookmark: activeBookmarks[index], index };
    activeBookmarks.splice(index, 1);
    renderDeleteCollection();
    toast.hidden = false;
    document.querySelector('#undo-delete').hidden = deleteVariant !== 'undo';
  }

  list.addEventListener('click', (event) => {
    const deleteButton = event.target.closest('[data-delete]');
    if (deleteButton) {
      if (deleteVariant === 'confirm') {
        const card = deleteButton.closest('.bookmark');
        if (!card.querySelector('.confirm-row')) {
          card.querySelector('.card-actions').insertAdjacentHTML('beforeend', `<div class="confirm-row"><span>Delete this bookmark?</span><button class="quiet-action" type="button" data-cancel-delete>Cancel</button><button class="danger-action" type="button" data-confirm-delete="${deleteButton.dataset.delete}">Delete bookmark</button></div>`);
        }
      } else {
        removeBookmark(deleteButton.dataset.delete);
      }
    }
    if (event.target.closest('[data-cancel-delete]')) renderDeleteCollection();
    const confirmButton = event.target.closest('[data-confirm-delete]');
    if (confirmButton) removeBookmark(confirmButton.dataset.confirmDelete);
  });

