473	            <a class="variant-link ${variant === 'check' ? 'active' : ''}" href="?flow=readlater&variant=check">B</a>
474	            <a class="variant-link ${variant === 'icon' ? 'active' : ''}" href="?flow=readlater&variant=icon">C</a>
